mapper.update:
UPDATE workspaces
SET write_lease_expires_at = DATE_ADD(UTC_TIMESTAMP(6), INTERVAL 30 MINUTE),
    updated_at = UTC_TIMESTAMP(6)
WHERE id = #{workspaceId} AND project_id = #{projectId}
  AND write_lease_agent_run_id = #{agentRunId} AND write_lease_token = #{token}
  AND write_lease_expires_at > UTC_TIMESTAMP(6)

UPDATE workspaces
SET write_lease_agent_run_id = NULL, write_lease_token = NULL, write_lease_expires_at = NULL,
    updated_at = UTC_TIMESTAMP(6)
WHERE id = #{workspaceId} AND project_id = #{projectId}
  AND write_lease_agent_run_id = #{agentRunId} AND write_lease_token = #{token}
